import assert from 'node:assert/strict'
import { createHash, generateKeyPairSync, sign } from 'node:crypto'
import { mkdir, mkdtemp, rm, writeFile } from 'node:fs/promises'
import { join, resolve } from 'node:path'
import { pathToFileURL } from 'node:url'
import { cpus, release } from 'node:os'
const root = resolve(import.meta.dir, '../..')
const roots = { before: join(import.meta.dir, 'before'), after: root }
const load = (base: string, name: string) => import(pathToFileURL(join(base, name)).href)
const samples: Record<string, unknown>[] = []
const hash = (bytes: Uint8Array | string) => createHash('sha256').update(bytes).digest('hex')
const modules = Object.fromEntries(await Promise.all(Object.entries(roots).map(async ([name, base]) => [name, {
  backend: (await load(base, 'packages/runtime/src/cef.ts')).CefBackend,
  peer: (await load(base, 'tests/helpers/native-peer.ts')).nativePeer,
  cache: (await load(base, 'packages/artifacts/src/cef-cache.ts')).withCefRuntime,
}])))
const fixtures: Record<string, any> = {}
const scratch = await mkdtemp(join(import.meta.dir, 'cache-measure-'))
try {
  for (const [name, module] of Object.entries(modules)) {
    const peer = await module.peer()
    let nativeId = 0
    peer.handle((command: any) => {
      peer.reply(command, command.op.endsWith('.create') ? { id: ++nativeId } : null)
      if (command.op === 'quit') peer.send({ v: 1, event: 'shutdown' })
    })
    const backend = new module.backend(peer.transport)
    const session = await backend.createSession({ persistence: 'ephemeral', partition: 'measure' })
    const windows = []
    for (let n = 0; n < 32; n++) windows.push(await backend.createWindow({ title: 'measure', bounds: { x: 0, y: 0, width: 600, height: 400 } }))
    for (let n = 0; n < 128; n++) await backend.createView({ window: windows[n % 32], session, url: 'app://ui/index.html', trust: { kind: 'remote' } })
    fixtures[name] = { peer, backend, target: nativeId }
  }
  const key = 'a'.repeat(64)
  const directory = join(scratch, key)
  await mkdir(join(directory, 'resources'), { recursive: true, mode: 0o700 })
  await writeFile(join(scratch, key + '.lock'), '', { mode: 0o600 })
  const identity = { kind: 'cef-runtime', version: '0.1.0', abi: 1, target: 'darwin-arm64', bun: '1.4.3', cef: '154.0.34', chromium: '154.0.8037.98', cefRs: 'b'.repeat(40), nativeToolchain: 'rust-1.91.0' }
  const files = [
    ['host', Buffer.from('host')], ['helper', Buffer.from('helper')], ['resources/bun', Buffer.from('bun')],
    ['resources/runtime.json', Buffer.from(JSON.stringify({ schema: 1, protocol: 1, bun_version: '1.4.3', cef_version: '154.0.34' }))],
    ['LICENSE', Buffer.from('Synthetic fixture only, not a runtime.')], ['large.bin', Buffer.alloc(64 * 1024 * 1024, 81)],
  ] as const
  const members: any[] = [{ path: 'resources', type: 'directory', mode: 0o700 }]
  for (const [path, bytes] of files) {
    const mode = path.endsWith('.json') ? 0o600 : 0o700
    await writeFile(join(directory, path), bytes, { mode })
    members.push({ path, type: 'file', mode, size: bytes.length, sha256: hash(bytes) })
  }
  const tarBytes = 1024 + members.reduce((n, m) => n + 512 + (m.type === 'file' ? Math.ceil(m.size / 512) * 512 : 0), 0)
  const manifest = { schema: 2, identity, archive: { url: 'https://fixture.invalid/runtime.tar.gz', size: 1, sha256: key, tarBytes, format: 'ustar-gzip' }, members, layout: { executable: 'host', bun: 'resources/bun', resources: 'resources', helpers: ['helper'] }, notices: ['LICENSE'], locales: 'all', debugSymbols: false }
  const keys = generateKeyPairSync('ed25519')
  const payload = Buffer.from(JSON.stringify(manifest))
  const options = { cacheRoot: scratch, expected: identity, offline: true, timeoutMs: 30000, allowedOrigins: ['https://fixture.invalid'], trustRoots: { fixture: keys.publicKey.export({ type: 'spki', format: 'pem' }).toString() }, envelope: { keyId: 'fixture', payload: payload.toString('base64'), signature: sign(null, payload, keys.privateKey).toString('base64') }, fetcher: async () => { throw new Error('Unexpected download') } }
  for (let iteration = -1; iteration < 8; iteration++) {
    for (const name of iteration % 2 === 0 ? ['before', 'after'] : ['after', 'before']) {
      const f = fixtures[name]!
      let count = 0
      const eventCount = 8192
      let complete!: () => void
      const done = new Promise<void>((resolve) => { complete = resolve })
      const remove = f.backend.observe((event: any) => { if (event.event === 'view.title' && ++count === eventCount) complete() })
      const wire = Buffer.from((JSON.stringify({ v: 1, event: 'view.title', target: f.target, data: { title: 'fixture' } }) + '\n').repeat(eventCount))
      let start = performance.now()
      f.peer.input.write(wire)
      await done
      const eventsMs = performance.now() - start
      remove()
      assert.equal(count, eventCount)
      start = performance.now()
      let counted = 0
      for (let n = 0; n < 50000; n++) counted += f.backend.diagnostics().views
      const diagnosticsMs = performance.now() - start
      assert.equal(counted, 50000 * 128)
      start = performance.now()
      for (let n = 0; n < 512; n++) await f.backend.nativeDiagnostics()
      const requestsMs = performance.now() - start
      start = performance.now()
      await modules[name]!.cache(options, async (path: string) => { assert.equal(path, directory) })
      const cacheMs = performance.now() - start
      samples.push({ name, iteration, warmup: iteration < 0, eventsMs, diagnosticsMs, requestsMs, cacheMs })
    }
  }
  const filesOfInterest = ['packages/runtime/src/cef.ts', 'packages/runtime/src/registry.ts', 'packages/runtime/src/native-transport.ts', 'packages/artifacts/src/cef-cache.ts']
  const sources: Record<string, unknown> = {}
  for (const [name, base] of Object.entries(roots)) {
    sources[name] = Object.fromEntries(await Promise.all(filesOfInterest.map(async (path) => [path, hash(await Bun.file(join(base, path)).bytes())])))
  }
  const median = (values: number[]) => { const ordered = values.toSorted((a, b) => a - b); return (ordered[3]! + ordered[4]!) / 2 }
  const medians: Record<string, any> = {}
  for (const name of Object.keys(roots)) {
    const trials = samples.filter((s) => s.name === name && !s.warmup)
    medians[name] = Object.fromEntries(['eventsMs', 'diagnosticsMs', 'requestsMs', 'cacheMs'].map((k) => [k, median(trials.map((v) => Number(v[k])))]))
  }
  const report = { schema: 1, classification: 'descriptive-local-microbenchmark', performanceClaimQualified: false, nativeBrowserExecuted: false, baseline: (await Bun.file(join(import.meta.dir, 'base.txt')).text()).trim(), bun: Bun.version, os: process.platform, arch: process.arch, osRelease: release(), cpu: cpus()[0]?.model, warmups: 1, trials: 8, order: 'alternating before/after; sequential workloads; no quiet-machine gate', workloads: { windows: 32, views: 128, deliveredTitleEvents: 8192, diagnosticReads: 50000, sequentialNativeProtocolRequests: 512, largeVerifiedFileBytes: 64 * 1024 * 1024, cacheProfile: 'synthetic authenticated offline cache; every file hashed, no CEF launch or download' }, sources, runnerSha256: hash(await Bun.file(import.meta.path).bytes()), samples, medians }
  await Bun.write(join(import.meta.dir, 'measurements.json'), JSON.stringify(report, null, 2) + '\n')
  console.log(JSON.stringify(medians, null, 2))
} finally {
  for (const fixture of Object.values(fixtures)) await fixture.backend.dispose()
  await rm(scratch, { recursive: true, force: true })
}
